436							t.Errorf("bad bucket %+v", b)
437							return
438						}
439					}
440					if sum != stats.Totals.TxCount {
441						t.Errorf("bucket counts %d != total %d", sum, stats.Totals.TxCount)
442						return
443					}
444				}
445			}()
446		}
